params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
Set-Location $repo
git fetch origin --prune | Out-Null
$targets=@(
'agent/control-test-narrow-test-scope-only-build-a-r-20260928133350-vrokm',
'fix/codex-quota-dispatch-circuit-20260929'
)
$deleted=@(); $missing=@(); $failed=@()
foreach($b in $targets){
  git show-ref --verify --quiet "refs/remotes/origin/$b"
  if($LASTEXITCODE -ne 0){ $missing += $b; continue }
  git push origin --delete $b
  if($LASTEXITCODE -eq 0){ $deleted += $b } else { $failed += $b }
}
git fetch origin --prune | Out-Null
[ordered]@{
  main=(git rev-parse origin/main | Out-String).Trim()
  deleted=$deleted
  missing=$missing
  failed=$failed
  remaining=@(git for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object {$_ -notin @('origin/HEAD','origin/main','origin/heaven-bridge')})
} | ConvertTo-Json -Depth 4
